286	func (s *Store) UpdatePATLastUsed(ctx context.Context, userID int32, tokenID string, lastUsed *timestamppb.Timestamp) error {
287		tokens, err := s.GetUserPersonalAccessTokens(ctx, userID)
288		if err != nil {
289			return err
290		}
291	
292		for _, token := range tokens {
293			if token.TokenId == tokenID {
294				token.LastUsedAt = lastUsed
295				break
296			}
297		}
298	
299		_, err = s.UpsertUserSetting(ctx, &storepb.UserSetting{
300			UserId: userID,
301			Key:    storepb.UserSetting_PERSONAL_ACCESS_TOKENS,
302			Value: &storepb.UserSetting_PersonalAccessTokens{
303				PersonalAccessTokens: &storepb.PersonalAccessTokensUserSetting{
304					Tokens: tokens,
305				},
306			},
307		})
308		return err
309	}
